// @ts-nocheck
import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

const view = (status, task0, task1, extra = {}) => ({
  status, task0, task1, retried0: false, retried1: false, processed: 0, ...extra,
});

test('happy path', async () => {
  const h = await create();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.equal((await h.inFlight()).length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.equal(await h.worker('x'), null);
  assert.equal((await h.workDone('worker0', 0)).ok, false);
  assert.equal((await h.workDone('worker0', 3)).ok, false);
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workDone('worker0', 2);
  await h.workDone('worker1', 1);
  const reports = await h.inFlight();
  assert.deepEqual(reports.map((m) => m.data).sort((a, b) => a.task - b.task), [
    { task: 0, outcome: 'completed', items: 2 },
    { task: 1, outcome: 'completed', items: 1 },
  ]);
  assert.equal((await h.run()).status, 'running');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', { processed: 3 }));
});

test('failure retried once', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1');
  assert.deepEqual((await h.inFlight())[0].data, { task: 1, outcome: 'failed', items: 0 });
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', { retried1: true }));
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workFailed('worker1'); await h.deliverAll();
  assert.equal((await h.run()).status, 'running');
  await h.workDone('worker0', 2); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', { retried1: true, processed: 2 }));
});

test('retry then success', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0'); await h.deliverAll();
  await h.workDone('worker0', 1); await h.workDone('worker1', 1); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', { retried0: true, processed: 2 }));
});

test('failure while cancelling is recorded', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel(); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'cancelled'));
});

test('timeout fails the task without retry and aborts the worker', async () => {
  const h = await create();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start(); await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  await h.workDone('worker1', 2); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed', { processed: 2 }));
});

test('late report after timeout is ignored and adds nothing', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0', 2);
  await h.taskTimeout(0);
  await h.taskTimeout(1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'failed'));
});

test('cancel with a completion in flight', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0', 2);
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.filter((m) => m.action === 'Abort').length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelled', 'completed', 'cancelled', { processed: 2 }));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

